编译失败是因为在 `thread::spawn` 的闭包里，用 `let a = Arc::clone(&a)` / `let b = Arc::clone(&b)` 把同名的 worker 函数 `a`、`b` 遮住了，闭包内 `a(...)` / `b(...)` 会被当成在“调用”`Arc`，从而报错。克隆锁时用 `a_lock`、`b_lock`（或 `a_clone`）即可保留函数名。

```rust
use concir_sync::Semaphore;
use std::sync::{Arc, Mutex};
use std::thread;

fn a(
    a: Arc<Mutex<()>>,
    b: Arc<Mutex<()>>,
    sa: Arc<concir_sync::Semaphore>,
    sb: Arc<concir_sync::Semaphore>,
    va: Arc<Mutex<u32>>,
) {
    let p_sa = sa.acquire();
    let _ga = a.lock().unwrap();
    p_sa.release();
    let _p_sb = sb.acquire();
    let _gb = b.lock().unwrap();
    *va.lock().unwrap() = 1;
}

fn b(
    a: Arc<Mutex<()>>,
    b: Arc<Mutex<()>>,
    sa: Arc<concir_sync::Semaphore>,
    sb: Arc<concir_sync::Semaphore>,
    vb: Arc<Mutex<u32>>,
) {
    let p_sb = sb.acquire();
    let _gb = b.lock().unwrap();
    p_sb.release();
    let _p_sa = sa.acquire();
    let _ga = a.lock().unwrap();
    *vb.lock().unwrap() = 1;
}

fn bystander(flag: Arc<Mutex<u64>>) {
    loop {
        if let Ok(mut f) = flag.try_lock() {
            *f = f.wrapping_add(1);
        }
    }
}

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));
    let sa = Semaphore::new(1);
    let sb = Semaphore::new(1);
    let flag = Arc::new(Mutex::new(0u64));
    let va = Arc::new(Mutex::new(0u32));
    let vb = Arc::new(Mutex::new(0u32));

    let ha = {
        let a_lock = Arc::clone(&a);
        let b_lock = Arc::clone(&b);
        let sa = Arc::clone(&sa);
        let sb = Arc::clone(&sb);
        let va = Arc::clone(&va);
        thread::spawn(move || {
            a(a_lock, b_lock, sa, sb, va);
        })
    };
    let hb = {
        let a_lock = Arc::clone(&a);
        let b_lock = Arc::clone(&b);
        let sa = Arc::clone(&sa);
        let sb = Arc::clone(&sb);
        let vb = Arc::clone(&vb);
        thread::spawn(move || {
            b(a_lock, b_lock, sa, sb, vb);
        })
    };
    let _hbyst = {
        let flag = Arc::clone(&flag);
        thread::spawn(move || bystander(flag))
    };

    ha.join().unwrap();
    hb.join().unwrap();

    let a_count = *va.lock().unwrap();
    let b_count = *vb.lock().unwrap();
    println!("DONE a={} b={}", a_count, b_count);
}
```
